insert into public.cards(set_id,external_id,name,number,rarity,image_url,weight,sell_value)
select s.id,x.external_id,x.name,x.number,x.rarity,x.image_url,x.weight,x.sell_value
from source x join public.card_sets s on s.slug=x.set_slug
on conflict(set_id,number) do update set name=excluded.name,rarity=excluded.rarity,image_url=excluded.image_url,weight=excluded.weight,sell_value=excluded.sell_value,active=true;
